 for(const tool of ['tts','audio_effects'])if(!blackTools.includes(tool))blackTools.push(tool);
 paths.tts='<path d="M4 8v8M8 4v16M12 7v10M16 3v18M20 8v8"/>';
 paths.audio_effects='<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>';
 let speech=null,project=null,chapter=0,epoch=0,saveTimer,pollTimer,playingJob='',lastAudio='',originalAudio='';
 let search='',favoriteOnly=false,filters={},voiceCollapsed=false,selectedText='',selectionStart=0,selectionEnd=0;
 let undo=[],redo=[],chain=[],effectsSource=null,fxSchema=[],dragIndex=null,fxFormat='wav',fxBypass=false;
 const rememberedJobs=new Set(),historyLimit=100;
