  $s('save').onclick=()=>saveProject();$s('project-name').oninput=markDirty;
  $s('project').onchange=()=>attempt(async()=>{const target=$s('project').value;await saveProject(false);if(!target){project=blankProject();chapter=0;drawStudio();return;}const r=await api('/speech/projects/'+encodeURIComponent(target));project=r.project||r;chapter=0;undo=[];redo=[];drawStudio();});
  $s('chapter').onchange=e=>{captureText();chapter=Number(e.target.value);undo=[];redo=[];drawStudio();};
  $s('chapter-add').onclick=()=>{captureText();const title=prompt('Chapter title:','Chapter '+(project.chapters.length+1));if(!title)return;project.chapters.push({id:crypto.randomUUID(),title,text:''});chapter=project.chapters.length-1;drawStudio();markDirty();};
  $s('chapter-rename').onclick=()=>{const title=prompt('Chapter title:',chapterData().title);if(title){chapterData().title=title;drawStudio();markDirty();}};
  $s('chapter-delete').onclick=()=>{if(project.chapters.length===1)return notify('Keep at least one chapter.');if(!confirm('Remove this chapter from the saved project?'))return;project.chapters.splice(chapter,1);chapter=0;drawStudio();markDirty();};
  $s('engine').onchange=e=>{captureText();captureOptions();const o=currentOptions();o.engine=e.target.value;o.task='IP';o.speed=1;delete o.blend;delete o.profile;const first=voices()[0];o.voice=first?.id||(o.engine==='kokoro'?'am_onyx':'US_James');if(project.speakers?.narrator)project.speakers.narrator={name:'Narrator',engine:o.engine,voice:o.voice};drawStudio();markDirty();};
  $('#sp-engine-options').onchange=event=>{captureOptions();if(event.target.id==='sp-task'){drawStudio();}markDirty();};
  for(const key of ['directory','format','title','artist','album','copyright','cover'])$s(key).oninput=()=>{if(key==='directory')project.output=output();else if(['title','artist','album','copyright'].includes(key)){currentOptions().metadata=currentOptions().metadata||{};currentOptions().metadata[key]=$s(key).value;}else currentOptions()[key]=$s(key).value;markDirty();};
  $s('preview').onclick=()=>generate('preview');$s('generate').onclick=()=>generate('document');$s('generate-selection').onclick=()=>generate('selection');$s('chapter-generate').onclick=()=>generate('chapter');
  $s('export').onclick=()=>generate('export');$s('effects').onclick=()=>openEffects(false);$s('master-chain').onclick=()=>openEffects(true);$s('books').onclick=bookBuilder;$s('mixer').onclick=voiceMixer;$s('install').onclick=modelManager;
  $s('undo').onclick=()=>historyMove(undo,redo);$s('redo').onclick=()=>historyMove(redo,undo);$s('find').onclick=findReplace;
