  $s('spoken').onclick=()=>attempt(async()=>{captureText();const r=await api('/speech/parse',{text:chapterData().text,style:currentOptions().style||'normal',pronunciation:project.pronunciation||{},pauses:project.pauses||{}});modal('Spoken text preview','<p class="sp-note">The source document is retained. Markers are interpreted before synthesis.</p><pre id="sp-spoken-result"></pre>',()=>{$s('spoken-result').textContent=r.spoken_text||r.spoken||r.segments?.filter(v=>v.text).map(v=>v.text).join('\n')||JSON.stringify(r,null,2);});});
  $s('voice-search').oninput=e=>{search=e.target.value;drawVoices();};for(const name of ['availability','language','accent','gender','pitch','origin','expression','sort'])$s('voice-'+name).oninput=e=>{filters[name]=e.target.value;favoriteOnly=filters.availability==='favorites';drawVoices();};
  $s('voice-create').onclick=()=>profileEditor();$s('voice-import').onclick=()=>fileJSON(value=>attempt(async()=>{const clean={...value};delete clean.id;delete clean.revision;await api('/speech/records/voices',clean);await loadState();drawVoices();}));
