 function chooseVoice(id){const switching=currentOptions().engine==='ming'&&currentOptions().task!=='IP';if(switching){currentOptions().task='IP';for(const key of ['reference_audio','reference_text','instructions','consent','attribute_speed','attribute_pitch','attribute_volume','dialect','emotion'])delete currentOptions()[key];}const profile=records('profiles').find(p=>p.id===id);const o=currentOptions();o.voice=id;o.language=profile?.language||voices().find(v=>v.id===id)?.language||o.language;if(profile?.blend)o.blend=structuredClone(profile.blend);else delete o.blend;delete o.profile;if(project.speakers?.narrator){project.speakers.narrator={...project.speakers.narrator,engine:o.engine,voice:profile?.voice||id,blend:profile?.blend||[]};}const recent=[id,...(speech.settings?.recent||[]).filter(v=>v!==id)].slice(0,30);speech.settings={...speech.settings,recent};void api('/speech/settings',{recent}).catch(e=>notify(e.message,true));$s('current-voice').textContent=voiceName(selectedVoice());if(switching)drawStudio();else drawVoices();markDirty();}
