 function playbackHTML(){return `<section class="sp-playback" aria-label="Audio playback"><div class="sp-playback-head"><strong>Production audio</strong><span id="sp-render-status" role="status">${playingJob?'Last job '+esc(playingJob.slice(0,8)):'No render yet'}</span><div class="sp-actions">${button('audio-ab','Original / processed')}${button('audio-fx','Audio Effects')}<a id="sp-audio-download" href="${esc(lastAudio)}" download hidden>Download audio</a></div></div><canvas id="sp-waveform" height="82" aria-label="Audio waveform"></canvas><audio id="sp-audio" controls preload="metadata" ${lastAudio?'src="'+esc(lastAudio)+'"':''}></audio><p class="sp-note" id="sp-audio-duration">Select a completed render to play or seek.</p></section>`;}
 function bindPlayback(){const audio=$s('audio');if(!audio)return;$s('audio-ab').disabled=!originalAudio||!lastAudio||originalAudio===lastAudio;$s('audio-ab').onclick=()=>{const source=audio.getAttribute('src')===originalAudio?lastAudio:originalAudio,time=audio.currentTime;audio.src=source;audio.onloadedmetadata=()=>{audio.currentTime=Math.min(time,audio.duration);};drawWaveFromURL(source);};$s('audio-fx').onclick=()=>{if(view==='audio_effects')$s('chain')?.scrollIntoView({block:'start',behavior:'smooth'});else openEffects(false);};audio.onloadedmetadata=()=>{$s('audio-duration').textContent=`${audio.duration.toFixed(2)} seconds · seek with the player or waveform`};$s('waveform').onclick=event=>{if(Number.isFinite(audio.duration)){const box=event.currentTarget.getBoundingClientRect();audio.currentTime=(event.clientX-box.left)/box.width*audio.duration;}};if(lastAudio)void drawWaveFromURL(lastAudio);}
 async function drawWaveFromURL(url){try{const response=await fetch(url,{credentials:'same-origin',cache:'no-store'});if(!response.ok)return;if(Number(response.headers.get('content-length'))>40_000_000){await response.body?.cancel();return;}const reader=response.body?.getReader();let buffer;if(reader){const chunks=[];let size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>40_000_000){await reader.cancel();return;}chunks.push(part.value);}const joined=new Uint8Array(size);let at=0;for(const part of chunks){joined.set(part,at);at+=part.length;}buffer=joined.buffer;}else buffer=await response.arrayBuffer();if(buffer.byteLength>40_000_000)return;const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;const context=new AudioContext(),decoded=await context.decodeAudioData(buffer);const canvas=$s('waveform');if(canvas)drawWave(canvas,decoded.getChannelData(0));await context.close();}catch{}}
 function drawWave(canvas,data){const ctx=canvas.getContext('2d'),width=canvas.width=Math.max(300,canvas.clientWidth*devicePixelRatio),height=canvas.height=82*devicePixelRatio;ctx.clearRect(0,0,width,height);ctx.strokeStyle='#baa36a';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<width;x++){const begin=Math.floor(x*data.length/width),end=Math.max(begin+1,Math.floor((x+1)*data.length/width));let peak=0;for(let k=begin;k<end;k++)peak=Math.max(peak,Math.abs(data[k]||0));ctx.moveTo(x,height/2-peak*height*.45);ctx.lineTo(x,height/2+peak*height*.45);}ctx.stroke();}
