 function speakerManager(){modal('Speaker assignments',`<div id="sp-speaker-list"></div>${button('speaker-add','Add speaker')}${button('speaker-save','Save assignments','primary')}`,()=>{let values=structuredClone(project.speakers||{});const draw=()=>{$s('speaker-list').innerHTML=Object.entries(values).map(([id,s])=>`<div class="sp-speaker-row" data-speaker="${esc(id)}"><label class="sp-field">Name<input data-speaker-name value="${esc(s.name||id)}"></label><label class="sp-field">Voice<select data-speaker-voice>${opts(speakerVoices().map(v=>[v.id,(v.engine||'')+' · '+voiceName(v)]),s.profile||s.voice)}</select></label><label class="sp-field">Rate<input data-speaker-rate type="number" min="0.5" max="2" step=".05" value="${s.speed||1}"></label><button data-speaker-remove="${esc(id)}" ${id==='narrator'?'disabled':''}>Remove</button></div>`).join('');$$('[data-speaker-remove]').forEach(b=>b.onclick=()=>{capture();delete values[b.dataset.speakerRemove];draw();});};const capture=()=>{$$('[data-speaker]').forEach(row=>{const s=values[row.dataset.speaker];s.name=$('[data-speaker-name]',row).value;s.voice=$('[data-speaker-voice]',row).value;const chosen=speakerVoices().find(v=>v.id===s.voice)||{};s.engine=chosen.engine||currentOptions().engine;s.language=chosen.language||'en';if(chosen.custom||chosen.blend||chosen.method){s.profile=chosen.id;s.voice=chosen.voice||chosen.id;s.blend=structuredClone(chosen.blend||[]);s.voice_effects=structuredClone(chosen.voice_effects||[]);}else{delete s.profile;delete s.blend;}s.speed=Number($('[data-speaker-rate]',row).value);});};draw();$s('speaker-add').onclick=()=>{capture();const id='speaker-'+crypto.randomUUID().slice(0,8);values[id]={name:'New speaker',voice:currentOptions().voice,engine:currentOptions().engine,speed:1};draw();};$s('speaker-save').onclick=()=>{capture();project.speakers=values;markDirty();$('#dialog').close();};});}
 function readingRules(){modal('Reading style and pronunciation',select('style','Reading style',records('styles').map(s=>[s.id,s.name||s.id]),currentOptions().style||'normal')+`<label class="sp-field">Pronunciation dictionary (one original = spoken replacement per line)<textarea id="sp-pronunciation">${esc(Object.entries(project.pronunciation||{}).map(([a,b])=>a+' = '+b).join('\n'))}</textarea></label><div class="sp-pause-grid">${[['comma',200],['period',400],['paragraph',750],['heading',900],['chapter',1250],['list',450],['quotation',250],['ellipsis',650],['scene',1500]].map(([name,value])=>input('pause-'+name,name+' pause (ms)',project.pauses?.[name]??value,'number','min="0" max="10000" step="50"')).join('')}</div><div class="sp-actions">${button('rules-save','Apply rules','primary')}${button('rules-preset','Save custom pacing')}${button('rules-manage','Manage presets')}</div>`,()=>{$s('style').onchange=()=>{const style=records('styles').find(v=>v.id===$s('style').value);for(const [k,v] of Object.entries(style?.pauses||{}))if($s('pause-'+k))$s('pause-'+k).value=v;};const capture=()=>{currentOptions().style=$s('style').value;project.pronunciation={};for(const line of $s('pronunciation').value.split('\n')){const pos=line.indexOf('=');if(pos>0)project.pronunciation[line.slice(0,pos).trim()]=line.slice(pos+1).trim();}project.pauses=Object.fromEntries($$('#dialog [id^="sp-pause-"]').map(el=>[el.id.slice(9),Number(el.value)]));};$s('rules-save').onclick=()=>{capture();markDirty();$('#dialog').close();};$s('rules-preset').onclick=()=>attempt(async()=>{capture();const name=prompt('Pacing preset name:');if(!name)return;await api('/speech/records/styles',{name,pauses:project.pauses,pronunciation:project.pronunciation});await loadState();readingRules();});$s('rules-manage').onclick=()=>manageRecords('styles');});}
