 function voiceMixer(){if(currentOptions().engine!=='kokoro')return notify('Native voice blending is available only for compatible Kokoro voices. Choose Kokoro to create a blend.',true);let blend=structuredClone(currentOptions().blend||[{voice:currentOptions().voice||'am_onyx',weight:1}]);modal('Voice Mixer · Kokoro',`<p class="sp-note">Mix original embeddings from the same Kokoro revision. Weights are saved with source voice IDs; this creates a preset, not a trained model.</p>${input('mix-name','Custom voice name','My Kokoro blend')}<div id="sp-mix-rows"></div><div class="sp-actions">${button('mix-add','Add voice')}${button('mix-normalize','Normalize')}${button('mix-random','Randomize')}${button('mix-reset','Reset')}</div><div class="sp-actions">${button('mix-preview','Preview blend')}${button('mix-original','Preview original')}${button('mix-save','Save blend','primary')}${button('mix-export','Export recipe')}</div>`,()=>{const read=()=>{$$('[data-mix-row]').forEach((row,i)=>{blend[i]={voice:$('select',row).value,weight:Number($('input[type="number"]',row).value)/100};});};const draw=()=>{$s('mix-rows').innerHTML=blend.map((b,i)=>`<div data-mix-row="${i}" class="sp-mix-row"><select aria-label="Blend voice ${i+1}">${opts(voices().map(v=>[v.id,voiceName(v)]),b.voice)}</select><input aria-label="Blend weight ${i+1}" type="range" min="0" max="100" step="1" value="${b.weight*100}"><input aria-label="Blend percentage ${i+1}" type="number" min="0" max="100" step="1" value="${Number((b.weight*100).toFixed(2))}"><span>%</span><button data-mix-remove="${i}" ${blend.length<2?'disabled':''}>Remove</button></div>`).join('');$$('[data-mix-row]').forEach(row=>{const range=$('input[type="range"]',row),number=$('input[type="number"]',row);range.oninput=()=>number.value=range.value;number.oninput=()=>range.value=number.value;});$$('[data-mix-remove]').forEach(b=>b.onclick=()=>{read();blend.splice(Number(b.dataset.mixRemove),1);draw();});};const normalized=()=>{read();const total=blend.reduce((a,b)=>a+b.weight,0);if(!(total>0))throw Error('At least one weight must be positive.');return blend.map(b=>({voice:b.voice,weight:b.weight/total}));};draw();$s('mix-add').onclick=()=>{read();blend.push({voice:voices()[0]?.id||'am_onyx',weight:0});draw();};$s('mix-normalize').onclick=()=>attempt(async()=>{blend=normalized();draw();});$s('mix-random').onclick=()=>{read();const raw=crypto.getRandomValues(new Uint32Array(blend.length)),sum=[...raw].reduce((a,b)=>a+b,0);blend=blend.map((b,i)=>({...b,weight:raw[i]/sum}));draw();};$s('mix-reset').onclick=()=>{blend=[{voice:'am_onyx',weight:1}];draw();};const recipe=()=>({name:$s('mix-name').value,engine:'kokoro',method:'blend',custom:true,blend:normalized(),model_revision:engine().revision||engine().model_revision||'',voice:blend[0].voice,language:currentOptions().language||'en'});$s('mix-save').onclick=()=>attempt(async()=>{await api('/speech/records/voices',recipe());await loadState();$('#dialog').close();drawVoices();});$s('mix-export').onclick=()=>attempt(async()=>downloadJSON(recipe().name,recipe()));$s('mix-preview').onclick=()=>attempt(async()=>{const r=await api('/speech/preview',{text:$s('preview-text')?.value||'The room was quiet, and the story was about to begin.',options:{...currentOptions(),blend:normalized()},output:output()});queueResponse(r,'Blend preview');});$s('mix-original').onclick=()=>generate('preview','am_onyx');});}
 function modelManager(){modal('Local speech models',`<div class="sp-model-list">${list(speech.engines).map(e=>`<article><h3>${esc(e.label||e.id)}</h3><p>${e.installed?'Installed · offline files available':'Not installed'} · ${e.download_bytes?bytes(e.download_bytes):esc(e.size_label||'Download size available from manifest')}</p><p class="sp-note">${esc(e.unavailable_reason||e.reason||e.limitation||e.notes||'')}</p><small>Revision: ${esc(e.revision||e.model_revision||'Not resolved')}</small><div class="sp-actions"><button data-model-install="${esc(e.id)}">${e.installed?'Repair / verify':'Review installation'}</button>${e.installed?`<button data-model-remove="${esc(e.id)}">Remove unused model</button>`:''}</div></article>`).join('')}</div>`,()=>{$$('[data-model-install]').forEach(b=>b.onclick=()=>attempt(async()=>{const e=list(speech.engines).find(v=>v.id===b.dataset.modelInstall);if(!confirm(`Approve installing ${e.label||e.id} into its isolated environment and downloading its verified model files? No manuscript or reference audio is uploaded.`))return;const r=await api('/speech/install',{engine:e.id,device:currentOptions().device||'cpu',consent:true});queueResponse(r,'Model installation');if(r.message)notify(r.message);$('#dialog').close();}));$$('[data-model-remove]').forEach(b=>b.onclick=()=>attempt(async()=>{if(!confirm('Remove only this unused speech model cache? Projects and profiles are retained.'))return;const r=await api('/speech/models/remove',{engine:b.dataset.modelRemove,consent:true});notify(r.message||'Model removal completed.');await loadState();modelManager();}));});}
 function importDocument(){modal('Import manuscript',input('import-path','Local document path','','text','placeholder="B:\\Books\\manuscript.epub"')+'<p class="sp-note">EPUB, PDF text, TXT, Markdown, HTML and SRT/VTT. No OCR or external media fetching.</p>'+button('import-browse','Browse')+button('import-open','Import chapters','primary'),()=>{$s('import-browse').onclick=()=>attempt(async()=>{const r=await api('/pick',{kind:'file'});if(r.paths?.[0])$s('import-path').value=r.paths[0];});$s('import-open').onclick=()=>attempt(async()=>{const result=await api('/speech/import',{path:$s('import-path').value});const imported=result.project||result;captureText();project={...blankProject(),...imported};if(imported.title&&!imported.name)project.name=imported.title;chapter=0;$('#dialog').close();drawStudio();await saveProject();});});}
 function bookBuilder(){captureText();modal('Audiobook Builder',`<div class="sp-book-chapters">${project.chapters.map((c,i)=>`<label><input type="checkbox" data-book-chapter="${i}" checked><strong>${esc(c.title)}</strong><small>${c.text.trim().split(/\s+/).filter(Boolean).length} words</small><button data-book-edit="${i}">Edit</button></label>`).join('')}</div><div class="sp-actions">${button('book-import','Import document')}${button('book-selected','Generate selected chapters','primary')}${button('book-all','Generate entire book')}${button('book-assemble','Assemble / export cached audio')}${button('book-queue','View production queue')}</div><p class="sp-note">Completed segments are reused when their text, model revision and settings match. Queue pause/cancel/retry controls remain in the Universal Queue.</p>`,()=>{$$('[data-book-edit]').forEach(b=>b.onclick=()=>{chapter=Number(b.dataset.bookEdit);$('#dialog').close();drawStudio();});$s('book-import').onclick=importDocument;$s('book-all').onclick=()=>{$('#dialog').close();generate('document');};$s('book-assemble').onclick=()=>{$('#dialog').close();generate('export');};$s('book-queue').onclick=()=>{$('#dialog').close();navigate('queue');};$s('book-selected').onclick=()=>attempt(async()=>{const ids=$$('[data-book-chapter]:checked').map(b=>project.chapters[Number(b.dataset.bookChapter)].id);if(!ids.length)throw Error('Select at least one chapter.');await saveProject(false);const r=await api('/speech/generate',{project_id:project.id,scope:'chapters',chapter_ids:ids,options:currentOptions(),output:output()});queueResponse(r,'Audiobook');$('#dialog').close();});});}
 function effectDefinition(type){return list(fxSchema).find(e=>e.id===type)||{};}
 function effectParams(effect,index){return Object.entries(effectDefinition(effect.type).parameters||{}).map(([name,def])=>{const val=effect.params?.[name]??def.default,label=def.label||name;if(['points','bands'].includes(def.type))return `<label class="sp-field sp-field-wide">${esc(label)} (JSON)<textarea data-effect-param="${esc(name)}" aria-label="${esc(label)}">${esc(JSON.stringify(val??[]))}</textarea></label>`;return def.type==='boolean'?`<label class="checkbox"><input data-effect-param="${esc(name)}" type="checkbox" ${val?'checked':''}>${esc(label)}</label>`:def.options||def.enum?`<label class="sp-field">${esc(label)}<select data-effect-param="${esc(name)}">${opts((def.options||def.enum).map(v=>Array.isArray(v)?v:[v,v]),val)}</select></label>`:`<label class="sp-field">${esc(label)}<input data-effect-param="${esc(name)}" type="${['number','integer'].includes(def.type)?'number':'text'}" value="${esc(val??'')}" ${def.min!=null?'min="'+def.min+'"':''} ${def.max!=null?'max="'+def.max+'"':''} step="${def.step||'any'}"></label>`;}).join('');}
 function captureChain(){if(!$s('chain'))return;$$('[data-effect-index]').forEach(row=>{const effect=chain[Number(row.dataset.effectIndex)];if(!effect)return;effect.enabled=$('[data-effect-enabled]',row).checked;effect.params=effect.params||{};$$('[data-effect-param]',row).forEach(el=>{const def=effectDefinition(effect.type).parameters?.[el.dataset.effectParam]||{};effect.params[el.dataset.effectParam]=el.type==='checkbox'?el.checked:['number','integer'].includes(def.type)?Number(el.value):['points','bands'].includes(def.type)?JSON.parse(el.value):def.options?.some(v=>typeof v==='number')?Number(el.value):el.value;});});}
 function drawChain(){if(!$s('chain'))return;$s('chain').innerHTML=chain.map((effect,index)=>`<article class="sp-effect" data-effect-index="${index}" draggable="true"><header><span class="sp-drag" aria-hidden="true">⠿</span><label><input data-effect-enabled type="checkbox" ${effect.enabled!==false?'checked':''}>${esc(effectDefinition(effect.type).label||effect.type)}</label><button data-effect-up="${index}" aria-label="Move ${esc(effect.type)} up" ${index===0?'disabled':''}>↑</button><button data-effect-down="${index}" aria-label="Move ${esc(effect.type)} down" ${index===chain.length-1?'disabled':''}>↓</button><button data-effect-reset="${index}">Reset</button><button data-effect-remove="${index}" aria-label="Remove ${esc(effect.type)}">×</button></header><details open><summary>Parameters</summary><div class="sp-effect-params">${effectParams(effect,index)}</div></details></article>`).join('')||'<p class="sp-note">Add a processor. Empty chains preserve the source audio.</p>';
  $$('[data-effect-index]').forEach(row=>{row.ondragstart=()=>{captureChain();dragIndex=Number(row.dataset.effectIndex);};row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();captureChain();const to=Number(row.dataset.effectIndex);if(dragIndex!==null){chain.splice(to,0,chain.splice(dragIndex,1)[0]);drawChain();}dragIndex=null;};});
  for(const [selector,delta] of [['up',-1],['down',1]])$$('[data-effect-'+selector+']').forEach(b=>b.onclick=()=>{captureChain();const at=Number(b.dataset[selector==='up'?'effectUp':'effectDown']);chain.splice(at+delta,0,chain.splice(at,1)[0]);drawChain();});
  $$('[data-effect-reset]').forEach(b=>b.onclick=()=>{captureChain();chain[Number(b.dataset.effectReset)].params={};drawChain();});$$('[data-effect-remove]').forEach(b=>b.onclick=()=>{captureChain();chain.splice(Number(b.dataset.effectRemove),1);drawChain();});
 }
 function effectsHTML(embedded=false){return `<section class="speech-effects" id="speech-effects"><header class="sp-heading"><div><span class="eyebrow">AUDIO PRODUCTION</span><h1>${embedded?'Processing chain':'Audio Effects'}</h1></div><div class="sp-actions">${embedded?button('fx-apply','Save chain','primary'):''}${button('fx-preset','Save preset')}${button('fx-presets','Load / manage presets')}${button('fx-preview','Preview')}${button('fx-render','Render / export','primary')}</div></header>${!embedded?`<div class="sp-sourcebar">${input('fx-path','Source audio',effectsSource?.path||'')}${button('fx-browse','Browse')}${button('fx-load','Load source')}</div>`:''}<div class="sp-effect-settings">${select('fx-add','Add processor',list(fxSchema).map(e=>[e.id,e.label||e.id]),list(fxSchema)[0]?.id)}${button('fx-add-button','Add effect')}<label class="checkbox"><input type="checkbox" id="sp-fx-bypass" ${fxBypass?'checked':''}>Bypass All</label>${select('fx-format','Export',['wav','flac','mp3','opus','m4b'],fxFormat)}${input('fx-start','Region start (seconds)',0,'number','min="0" step=".01"')}${input('fx-end','Region end (blank = full)','','number','min="0" step=".01"')}</div><div id="sp-chain" class="sp-chain"></div><div class="sp-editor-footer"><span id="sp-status" role="status">Ordered, non-destructive processing</span>${!embedded?input('fx-directory','Export directory',''):''}</div>${!embedded?playbackHTML():''}</section>`;}
 function bindEffects(embedded=false,onApply,layer='master'){drawChain();$s('fx-add-button').onclick=()=>{captureChain();chain.push({type:$s('fx-add').value,enabled:true,params:{}});drawChain();};$s('fx-bypass').onchange=e=>fxBypass=e.target.checked;$s('fx-format').onchange=e=>fxFormat=e.target.value;$s('fx-preset').onclick=()=>attempt(async()=>{captureChain();const name=prompt('Effects preset name:');if(!name)return;await api('/speech/records/effects',{name,chain,bypass:fxBypass,favorite:false});await loadState();notify('Effects preset saved.');});$s('fx-presets').onclick=()=>{const presets=records('effects');modal('Effects presets',select('fx-preset-choice','Preset',presets.map(p=>[p.id,p.name]),presets[0]?.id)+button('fx-preset-load','Load')+button('fx-preset-manage','Manage / import'),()=>{$s('fx-preset-load').onclick=()=>{const p=presets.find(p=>p.id===$s('fx-preset-choice').value);if(p){chain=structuredClone(p.chain||[]);fxBypass=!!p.bypass;}$('#dialog').close();if(embedded)openEffects(true);else renderEffects();};$s('fx-preset-manage').onclick=()=>manageRecords('effects');});};if(embedded){$s('fx-apply').onclick=()=>{captureChain();onApply?.();$('#dialog').close();markDirty();};$s('fx-preview').onclick=()=>{captureChain();onApply?.();$('#dialog').close();generate(layer==='segment'?'selection':'preview');};$s('fx-render').onclick=()=>{captureChain();onApply?.();$('#dialog').close();generate(layer==='segment'?'selection':'document');};}else{$s('fx-browse').onclick=()=>attempt(async()=>{const r=await api('/pick',{kind:'file'});if(r.paths?.[0])$s('fx-path').value=r.paths[0];});$s('fx-load').onclick=()=>loadEffectSource();$s('fx-preview').onclick=()=>renderEffectJob(true);$s('fx-render').onclick=()=>renderEffectJob(false);bindPlayback();}}
 async function renderEffects(){const token=++epoch;$('#main').innerHTML='<p class="sp-note">Loading audio processors…</p>';try{await loadState();const r=await api('/speech/effects-schema');fxSchema=Array.isArray(r)?r:r.effects||r.schema||[];if(token!==epoch||view!=='audio_effects')return;$('#main').innerHTML=effectsHTML();bindEffects();}catch(error){if(token===epoch)$('#main').textContent=error.message;}}
 async function openEffects(master=false){const layer=master==='segment'?'segment':master?'master':'voice';master=layer==='master';captureText();await attempt(async()=>{const r=await api('/speech/effects-schema');fxSchema=Array.isArray(r)?r:r.effects||r.schema||[];chain=structuredClone(layer==='segment'?project.selection_chain||[]:master?currentOptions().master_effects||project.master_chain||[]:currentOptions().voice_effects||[]);fxBypass=master?!!project.master_bypass:false;modal(layer==='segment'?'Selection processing · Generate selection only':master?'Master processing':'Voice processing',effectsHTML(true),()=>bindEffects(true,()=>{if(layer==='segment'){project.selection_chain=structuredClone(chain);if(selectionEnd>selectionStart){const entry={chapter_id:chapterData().id,start:selectionStart,end:selectionEnd,chain:fxBypass?[]:structuredClone(chain),source_text:chapterData().text.slice(selectionStart,selectionEnd)};project.segment_processing=(project.segment_processing||[]).filter(v=>v.chapter_id!==entry.chapter_id||v.start!==entry.start||v.end!==entry.end);project.segment_processing.push(entry);}}else if(master){currentOptions().master_effects=fxBypass?[]:structuredClone(chain);}else currentOptions().voice_effects=fxBypass?[]:structuredClone(chain);},layer));});}
 async function loadEffectSource(){return attempt(async()=>{const path=$s('fx-path').value;const registered=await api('/register',{paths:[path]});effectsSource=registered.sources[0];const result=await api('/speech/waveform',{source_id:effectsSource.id});originalAudio=result.audio_url||'/api/speech/source-audio?source_id='+encodeURIComponent(effectsSource.id);lastAudio=originalAudio;const audio=$s('audio');audio.src=lastAudio;if(result.peaks||result.samples)drawWave($s('waveform'),result.peaks||result.samples);else drawWaveFromURL(lastAudio);status('Loaded · original source retained.');});}
